/** Ordered production generation; cache only verified current generated bytes. */
import {
  readFileSync,
  readdirSync,
  existsSync,
  mkdirSync,
  writeFileSync,
} from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, URL } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
function files(path) {
  if (!existsSync(path)) return [];
  return readdirSync(path, { withFileTypes: true }).flatMap((entry) => {
    const child = `${path}/${entry.name}`;
    if (entry.isDirectory())
      return entry.name === 'build' || entry.name === 'generated'
        ? []
        : files(child);
    return [child];
  });
}
const digest = (path) =>
  createHash('sha256').update(readFileSync(path)).digest('hex');
const inputPaths = [
  ...files(`${root}contracts`).filter((path) => !path.includes('/.gradle/')),
  ...files(`${root}build-tools/contracts`),
  ...files(`${root}tests/contracts`).filter((path) =>
    path.endsWith('.graphql'),
  ),
  ...files(`${root}frontend/src`).filter((path) => path.endsWith('.graphql')),
  ...[
    'generate-contracts.mjs',
    'generate-graphql.mjs',
    'generate-json-types.mjs',
    'generate-tokens.mjs',
    'contracts.gradle.kts',
  ].map((path) => `${root}build-tools/${path}`),
  `${root}docs/design-system/tokens.json`,
  `${root}package-lock.json`,
  `${root}gradle/libs.versions.toml`,
  `${root}gradle/verification-metadata.xml`,
  `${root}gradle/wrapper/gradle-wrapper.properties`,
].sort();
const inputs = Object.fromEntries(
  inputPaths.map((path) => [path.slice(root.length), digest(path)]),
);
const manifestPath = `${root}build/contract-generation.json`;
if (!process.argv.includes('--force') && existsSync(manifestPath)) {
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
  if (
    Object.keys(manifest.outputs).length > 0 &&
    JSON.stringify(inputs) === JSON.stringify(manifest.inputs) &&
    Object.entries(manifest.outputs).every(
      ([path, sha]) =>
        existsSync(`${root}${path}`) && digest(`${root}${path}`) === sha,
    )
  ) {
    console.log('Contract generation inputs and output bytes are current.');
    process.exit(0);
  }
}
for (const argv of [
  [process.execPath, 'build-tools/generate-graphql.mjs'],
  [
    './gradlew',
    ':contracts:grpc:generateProto',
    '--no-daemon',
    '--console',
    'plain',
  ],
]) {
  const result = spawnSync(argv[0], argv.slice(1), {
    cwd: root,
    stdio: 'inherit',
  });
  if (result.error || result.status !== 0) process.exit(result.status ?? 2);
}
function generatedFiles(path) {
  if (!existsSync(path)) return [];
  return readdirSync(path, { withFileTypes: true }).flatMap((entry) =>
    entry.isDirectory()
      ? generatedFiles(`${path}/${entry.name}`)
      : [`${path}/${entry.name}`],
  );
}
const outputPaths = [
  'frontend/src/lib/generated',
  'mcp/src/generated',
  'services/core/build/generated/sources/graphql',
  'services/core/build/generated/resources/contracts',
  'contracts/grpc/build/generated',
  'contracts/grpc/build/descriptors',
]
  .flatMap((path) => generatedFiles(`${root}${path}`))
  .sort();
if (!outputPaths.length)
  throw new Error('Required generated outputs are absent');
mkdirSync(`${root}build`, { recursive: true });
writeFileSync(
  manifestPath,
  JSON.stringify(
    {
      inputs,
      outputs: Object.fromEntries(
        outputPaths.map((path) => [path.slice(root.length), digest(path)]),
      ),
    },
    null,
    2,
  ) + '\n',
);
